-- NET-RO1.4 — additive private web-research staging only.
-- No inserts into public Network, no auth accounts, no personal contact extraction,
-- no rights clearance or technical certification implied by public website evidence.
-- Project owner decision: online sources first, site owners enrich by claiming later.
CREATE TABLE IF NOT EXISTS private.network_web_research_seeds (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  country_code text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
  canonical_domain text NOT NULL CHECK (
      canonical_domain ~ '^[a-z0-9][a-z0-9.-]*[.][a-z]{2,24}$'
      AND canonical_domain NOT LIKE '%..%'
  ),
  display_name text NOT NULL CHECK (length(btrim(display_name)) BETWEEN 3 AND 255),
  proposed_role text NOT NULL CHECK (
    proposed_role IN ('producer','trader_distributor','processor_service_provider','end_user')
  ),
  source_url text NOT NULL CHECK (source_url ~ '^https://[^[:space:]<>]+$' AND length(source_url) <= 2000),
  source_summary text NOT NULL CHECK (length(btrim(source_summary)) BETWEEN 25 AND 1000),
  source_kind text NOT NULL DEFAULT 'first_party_web',
  review_lane text NOT NULL DEFAULT 'web_profile_review_pending',
  claim_status text NOT NULL DEFAULT 'unclaimed' CHECK (claim_status IN ('unclaimed','claim_pending','claimed')),
  verification_status text NOT NULL DEFAULT 'web_sourced_unverified',
  publication_status text NOT NULL DEFAULT 'not_published' CHECK (publication_status IN ('not_published','withheld','published')),
  research_id text NOT NULL UNIQUE,
  batch_key text NOT NULL,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT network_web_research_seeds_country_domain_unique UNIQUE(country_code,canonical_domain),
  CONSTRAINT network_web_research_seeds_never_published
      CHECK (publication_status <> 'published')
);
ALTER TABLE private.network_web_research_seeds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.network_web_research_seeds FROM PUBLIC;
REVOKE ALL ON private.network_web_research_seeds FROM anon,authenticated;
GRANT SELECT, INSERT, UPDATE ON private.network_web_research_seeds TO service_role;
-- No policy for end users: service_role (and DB owner) only. The public directory
-- must use its existing reviewed publication pathway, never select this table.
ON CONFLICT (country_code,canonical_domain) DO NOTHING;
